// A malformed key must never reach a log. The bech32 decoder quotes its whole input in its errors
// (@scure/base: "Invalid checksum in <input>"), and on 10-23 nvoy-lukedog-broker-1 logged its own
// transport key that way. Every decode of a credential names the credential, never the value.
// Every key here is generated by this run; nothing in this file is real key material.
import { spawnSync } from 'node:child_process'
import { mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import * as nip19 from 'nostr-tools/nip19'
import { generateSecretKey, getPublicKey } from 'nostr-tools/pure'
import { secretKey } from '../mcp/tools/secret_key.mjs'
import { makeBunkerSigner } from '../mcp/tools/nip46-signer.mjs'
import { brokerSigner } from '../mcp/tools/broker_signer.mjs'
import { loadIdentity } from '../mcp/dist/identity.js'

let fails = 0
const ok = (name, value) => { console.log(`${value ? 'ok  ' : 'FAIL'} — ${name}`); if (!value) fails++ }
const thrown = f => { try { f(); return '' } catch (error) { return String(error?.message ?? error) } }
// A leak is the whole value or any long run of it.
const leaks = (text, raw) => [raw, raw.slice(5, 25), raw.slice(-20)].some(part => text.includes(part))

const good = nip19.nsecEncode(generateSecretKey())
const hexChars = n => Buffer.from(generateSecretKey()).toString('hex').slice(0, n)
const malformed = {
  'an nsec with a bad checksum': good.slice(0, -1) + (good.at(-1) === 'q' ? 'p' : 'q'),
  'an over-long nsec': good + 'q'.repeat(30),
  // The 10-23 shape: a hex key reaching an nsec-only decoder is read as bech32 split at its last
  // "1", and quoted when what follows holds no "b" (outside the bech32 alphabet).
  'a hex key where only an nsec is accepted': hexChars(32) + '1' + hexChars(31).replace(/[1b]/g, 'c'),
}

for (const [shape, raw] of Object.entries(malformed)) {
  ok(`the bare decoder quotes ${shape} (so a leak would be visible here)`, leaks(thrown(() => nip19.decode(raw)), raw))
}

// --- the shared decoder ---
for (const [shape, raw] of Object.entries(malformed)) {
  const message = thrown(() => secretKey(raw, 'NVOY_TEST_KEY', { hex: false }))
  ok(`secretKey refuses ${shape}, naming the credential and not the value`, /NVOY_TEST_KEY/.test(message) && !leaks(message, raw))
}
{
  const sk = generateSecretKey(), hex = Buffer.from(sk).toString('hex')
  ok('secretKey still decodes a valid nsec', Buffer.from(secretKey(nip19.nsecEncode(sk), 'x')).equals(Buffer.from(sk)))
  ok('secretKey still decodes 64-char hex where hex is allowed', Buffer.from(secretKey(`${hex}\n`, 'x')).equals(Buffer.from(sk)))
  ok('secretKey refuses an npub as a secret key', /x is not a valid/.test(thrown(() => secretKey(nip19.npubEncode(getPublicKey(sk)), 'x'))))
}

// --- the Bunker transport key ---
const bunkerUri = `bunker://${getPublicKey(generateSecretKey())}?relay=wss://relay.invalid&secret=s`
// makeBunkerSigner takes hex too, so for it only the bech32 shapes are malformed.
for (const [shape, raw] of Object.entries(malformed).filter(([shape]) => !shape.startsWith('a hex key'))) {
  const message = thrown(() => makeBunkerSigner(bunkerUri, raw, { clientSource: 'Bunker client credential at /run/test/client' }))
  ok(`makeBunkerSigner refuses ${shape} without quoting it`, /\/run\/test\/client/.test(message) && !leaks(message, raw))
}

// --- the broker signer, both branches, from a credential file ---
const dir = mkdtempSync(join(tmpdir(), 'nvoy-decode-leak-'))
const credentialFile = join(dir, 'client'), uriFile = join(dir, 'uri')
writeFileSync(uriFile, `${bunkerUri}\n`)
const raw = malformed['an nsec with a bad checksum']
writeFileSync(credentialFile, `${raw}\n`, { mode: 0o600 })
const savedEnv = { ...process.env }
for (const [branch, uri] of [['local key', ''], ['Bunker', uriFile]]) {
  Object.assign(process.env, { NVOY_BROKER_CREDENTIAL: credentialFile, NVOY_BUNKER_URI_FILE: uri })
  const message = thrown(() => brokerSigner(m => { throw new Error(m) }))
  ok(`brokerSigner (${branch}) names the credential file and not the key`, message.includes(credentialFile) && !leaks(message, raw))
}
process.env = savedEnv

// --- the MCP server identity (mcp/src/identity.ts) ---
{
  const message = thrown(() => loadIdentity([], { NVOY_NSEC: raw }))
  ok('loadIdentity names NVOY_NSEC and not the key', /NVOY_NSEC/.test(message) && !leaks(message, raw))
  const clientMessage = thrown(() => loadIdentity([], { NVOY_SIGNER: 'nip46', NVOY_BUNKER_URI: bunkerUri, NVOY_NIP46_CLIENT_NSEC_FILE: credentialFile }))
  ok('loadIdentity names the NIP-46 client credential file and not the key', clientMessage.includes(credentialFile) && !leaks(clientMessage, raw))
  const ncryptsecFile = join(dir, 'ncryptsec'), junk = raw.replace(/^nsec1/, 'ncryptsec1')
  writeFileSync(ncryptsecFile, junk)
  const ncryptMessage = thrown(() => loadIdentity([], { NVOY_NCRYPTSEC_FILE: ncryptsecFile, NVOY_NCRYPTSEC_PASSPHRASE: 'test' }))
  ok('loadIdentity names the ncryptsec file and not its contents', ncryptMessage.includes(ncryptsecFile) && !leaks(ncryptMessage, junk))
}

// --- the standalone tools: each dies naming its credential, with nothing of the key in its output ---
const tools = [
  ['inbox', ['mcp/tools/inbox.mjs'], { NVOY_NSEC: raw }, /NVOY_NSEC/],
  ['relay-send', ['mcp/tools/relay-send.mjs'], { NVOY_NSEC: raw, DRY_RUN: '1', WAGGLE_BRIDGE_PUBKEY: getPublicKey(generateSecretKey()) }, /NVOY_NSEC/],
  ['wake-watcher', ['mcp/tools/wake-watcher.mjs'], { NVOY_NSEC: raw }, /NVOY_NSEC/],
  ['attention (local key)', ['mcp/tools/attention.mjs'], { NVOY_NSEC: raw }, /NVOY_NSEC/],
  ['attention (Bunker client file)', ['mcp/tools/attention.mjs'], { NVOY_BUNKER_URI_FILE: uriFile, NVOY_NIP46_CLIENT_NSEC_FILE: credentialFile }, new RegExp(credentialFile.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))],
  ['concord', ['mcp/tools/concord.mjs'], { NVOY_NSEC: raw }, /NVOY_NSEC/],
  ['nvoy-ttl', ['bin/nvoy-ttl.mjs'], { NVOY_TTL_NSEC: raw }, /NVOY_TTL_NSEC/],
]
for (const [name, args, env, names] of tools) {
  const run = spawnSync(process.execPath, args, { encoding: 'utf8', input: '', timeout: 15000,
    env: { PATH: process.env.PATH, HOME: dir, NVOY_RELAYS: 'wss://relay.invalid', ...env } })
  const out = `${run.stdout}${run.stderr}`
  ok(`${name} dies naming its credential, without the key`, run.status !== 0 && names.test(out) && !leaks(out, raw))
}
rmSync(dir, { recursive: true, force: true })

// --- no tool reintroduces the bare idiom that leaked ---
const bare = /startsWith\('nsec1'\)\s*\?\s*(nip19\.)?decode\(/
const offenders = readdirSync('mcp/tools').filter(f => f.endsWith('.mjs') && bare.test(readFileSync(join('mcp/tools', f), 'utf8')))
ok(`no tool decodes a credential with a bare nip19 decode${offenders.length ? ` (${offenders.join(', ')})` : ''}`, !offenders.length)

console.log(fails ? `\n${fails} FAILED` : '\nall passed')
process.exit(fails ? 1 : 0)
